input.script:
const uno = part("uno", "arduino-uno");
const board = part("board", "breadboard");
const receiver = part("ir_rx", "ir-receiver");
const remote = part("remote", "ir-remote");
const motor = part("motor", "dc-motor");
const battery = part("battery", "battery-9v");
const switcher = part("motor_q", "npn-transistor");
const flyback = part("flyback", "rectifier-diode");
const baseR = part("base_r", "resistor", { resistance: 1000 });
const statusR = part("status_r", "resistor", { resistance: 220 });
const status = part("status_led", "led", { color: "green" });

mount(receiver, board);
mount(switcher, board);
mount(flyback, board);
mount(baseR, board);
mount(statusR, board);
mount(status, board);

near(board, uno, "right");
near(receiver, uno, "right");
near(remote, receiver, "above");
near(motor, board, "right");
near(battery, motor, "below");
near(switcher, receiver, "below");
near(flyback, switcher, "above");
near(baseR, switcher, "below");
near(statusR, receiver, "left");
near(status, statusR, "left");

const drive = stage("motor-drive", motor, switcher, baseR, flyback);
const input = stage("ir-control", receiver, remote);
const indicator = stage("status-indicator", statusR, status);
flow(uno, input, drive, motor);
flow(uno, indicator);

connect("uno:2", "ir_rx:DAT", { role: "signal", id: "ir-data" });
power("uno:5V", "ir_rx:VCC");
ground("battery:-", "uno:GND.3", "ir_rx:GND", "motor_q:E", "status_led:C");

connect("uno:5", "base_r:1", { role: "signal", id: "motor-pwm" });
connect("base_r:2", "motor_q:B", { role: "signal", id: "base-drive" });
connect("battery:+", "motor:1", { role: "power", id: "motor-supply" });
connect("motor:2", "motor_q:C", { role: "signal", id: "switched-motor-return" });
connect("flyback:C", "motor:1", { role: "power", id: "flyback-positive" });
connect("flyback:A", "motor:2", { role: "signal", id: "flyback-return" });

connect("uno:13", "status_r:1", { role: "signal", id: "status-drive" });
connect("status_r:2", "status_led:A", { role: "signal", id: "status-led-feed" });

code(uno, `
const int IR_PIN = 2;
const int MOTOR_PWM = 5;
const int STATUS_LED = 13;

void setup() {
  pinMode(IR_PIN, INPUT);
  pinMode(MOTOR_PWM, OUTPUT);
  pinMode(STATUS_LED, OUTPUT);
}

void loop() {
  // Deterministic reference mode: motor forward at a visible duty cycle.
  analogWrite(MOTOR_PWM, 180);
  digitalWrite(STATUS_LED, HIGH);
  delay(20);
}
`);
